def get_stats():
    from collections import Counter
    cats = Counter(e["category"] for e in exercises)
    equips = Counter(eq for e in exercises for eq in e["equipment"])
    goals = Counter(g for e in exercises for g in e["goal"])
    types = Counter(e.get("type","сила") for e in exercises)
    muscles_all = Counter(m for e in exercises for m in e["muscles"])
    print(f"Всього вправ: {len(exercises)}")
    print("Категорії:")
    for cat, n in cats.most_common(): print(f"  {cat}: {n}")
    print("Обладнання (топ 20):")
    for eq, n in equips.most_common(20): print(f"  {eq}: {n}")
    print("Цілі:")
    for g, n in goals.most_common(): print(f"  {g}: {n}")
    print("Типи:")
    for t, n in types.most_common(): print(f"  {t}: {n}")
    print("Топ 20 м'язів:")
    for m, n in muscles_all.most_common(20): print(f"  {m}: {n}")


def get_exercises(equipment=None, muscles=None, level=None, goal=None, category=None, ex_type=None):
    result = exercises
    if equipment: result = [e for e in result if any(eq in e["equipment"] for eq in equipment)]
    if muscles: result = [e for e in result if any(m in e["muscles"] for m in muscles)]
    if level: result = [e for e in result if level in e["level"]]
    if goal: result = [e for e in result if goal in e["goal"]]
    if category: result = [e for e in result if e["category"] == category]
    if ex_type: result = [e for e in result if e.get("type") == ex_type]
    return result


def get_alternatives(exercise_name):
    for ex in exercises:
        if ex["name"] == exercise_name:
            return ex["alternatives"]
    return []


def find_by_muscle(muscle, equipment=None, level=None):
    return get_exercises(muscles=[muscle], equipment=equipment, level=level)


def get_for_user(location, equipment_list, goal, level):
    result = [e for e in exercises
              if any(eq in e["equipment"] for eq in equipment_list)
              and goal in e["goal"]
              and level in e["level"]
              and e.get("type") == "сила"]
    return result


if __name__ == "__main__":
    get_stats()
    print("--- ПРИКЛАД: Груди + гантелі + рівень 1 ---")
    chest = get_exercises(equipment=["гантелі"], muscles=["груди"], level=1)
    for e in chest: print(f"  - {e['name']}")
    print("--- ПРИКЛАД: Ноги + власна вага + маса ---")
    legs = get_exercises(equipment=["власна вага"], muscles=["квадрицепс"], goal="маса")
    for e in legs: print(f"  - {e['name']}")
